(() => {
  // ==========================================================
  // GMJ NETVISION - RC4 RESEND v2
  // Reenvio operacional de mitigacao existente
  // ==========================================================

  const PATCH_VERSION = 'rc4-resend-v2';
  const __rBody = $json.body ?? $json;

  if (__rBody && __rBody.event === 'MITIGATION_STATUS_RESEND') {
    const __rEsc = (v) =>
      v === null || v === undefined
        ? ''
        : String(v)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/\r/g, '')
            .trim();

    const __rUp = (v) =>
      typeof v === 'string' ? v.trim().toUpperCase() : '';

    const __rProfileId = __rBody.profileId;

    const __rProfileOk =
      typeof __rProfileId === 'string' &&
      __rProfileId.length > 0 &&
      __rProfileId.length <= 160;

    const __rSimulado = __rBody.simulation === true;
    const __rVerificado = __rBody.verified === true;

    const __rEstado = __rUp(
      __rBody.mitigationState ??
      __rBody.mitigationStatus ??
      __rBody.state ??
      __rBody.status
    );

    const __rEstadoOk = __rEstado === 'MITIGATED';
    const __rRb = __rBody.readback ?? __rBody.readBack ?? null;
    const __rBogon = __rBody.bogonNode ?? null;
    const __rMit = __rBody.mitigationNode ?? __rBody.node ?? null;

    // Fail-closed: condicao invalida bloqueia o envio.
    let __rMotivo = null;

    if (!__rProfileOk) {
      __rMotivo = 'PROFILE_INVALIDO';
    } else if (__rSimulado) {
      __rMotivo = 'SIMULACAO';
    } else if (!__rVerificado) {
      __rMotivo = 'NAO_VERIFICADO';
    } else if (!__rEstadoOk) {
      __rMotivo = 'ESTADO_NAO_MITIGADO';
    } else if (__rRb === null || typeof __rRb !== 'object') {
      __rMotivo = 'READBACK_AUSENTE';
    } else if (__rRb.verified !== true) {
      __rMotivo = 'READBACK_NAO_VERIFICADO';
    } else if (__rUp(__rRb.state) !== 'MITIGATED') {
      __rMotivo = 'READBACK_ESTADO';
    } else if (__rRb.policy !== (__rBody.policy ?? null)) {
      __rMotivo = 'READBACK_POLICY';
    } else if (__rBogon === null || __rMit === null) {
      __rMotivo = 'READBACK_PAR_FALTANDO';
    } else if (
      Number(__rRb.bogonNode) !== Number(__rBogon) ||
      Number(__rRb.mitigationNode) !== Number(__rMit)
    ) {
      __rMotivo = 'READBACK_PAR_DIVERGENTE';
    } else if (
      typeof __rRb.readAt !== 'string' ||
      __rRb.readAt.trim().length === 0
    ) {
      __rMotivo = 'READBACK_SEM_READAT';
    }

    if (__rMotivo !== null) {
      return {
        EVENTO: __rBody.event,
        PATCH: PATCH_VERSION,
        REENVIO: true,
        RESEND_VALIDO: false,
        REAL_ACTIVATED: false,
        MOTIVO: __rMotivo,
        PROFILE_ID:
          typeof __rProfileId === 'string' ? __rProfileId : null,
        telegramText: '',
      };
    }

    const __rIf =
      __rBody.interfaceName ?? __rBody.interface;

    const __rTargets = Array.isArray(__rBody.sharedPolicyTargets)
      ? __rBody.sharedPolicyTargets
      : [];

    const __rPeers = Array.isArray(__rBody.affectedPeers)
      ? __rBody.affectedPeers
      : [];

    const __rLines = [];

    __rLines.push(
      '🔄 <b>MITIGAÇÃO EXISTENTE — REENVIO PARA TESTE OPERACIONAL</b>'
    );
    __rLines.push('');

    if (__rBody.customer)
      __rLines.push('<b>Cliente:</b> ' + __rEsc(__rBody.customer));

    if (__rBody.device)
      __rLines.push('<b>Equipamento:</b> ' + __rEsc(__rBody.device));

    if (__rIf)
      __rLines.push('<b>Interface:</b> ' + __rEsc(__rIf));

    if (__rBody.addressFamily)
      __rLines.push('<b>Família:</b> ' + __rEsc(__rBody.addressFamily));

    __rLines.push('');

    if (__rBody.policy)
      __rLines.push('<b>Policy:</b> ' + __rEsc(__rBody.policy));

    if (__rBogon !== null)
      __rLines.push('<b>Node BOGONS:</b> ' + __rEsc(__rBogon));

    if (__rMit !== null)
      __rLines.push('<b>Node mitigação:</b> ' + __rEsc(__rMit));

    if (__rBody.rt)
      __rLines.push('<b>RT:</b> ' + __rEsc(__rBody.rt));

    if (__rBody.peer)
      __rLines.push('<b>Peer principal:</b> ' + __rEsc(__rBody.peer));

    if (__rPeers.length > 0)
      __rLines.push(
        '<b>Peers afetados:</b> ' + __rEsc(__rPeers.join(', '))
      );

    __rLines.push('');

    __rLines.push(
      'ℹ️ Estado <b>já ativo</b> no equipamento — reenvio operacional; <b>não</b> é uma nova ativação.'
    );

    __rLines.push(
      '🏷️ <b>Perfil:</b> ' + __rEsc(__rProfileId)
    );

    __rLines.push(
      '🕒 Readback verificado em ' + __rEsc(__rRb.readAt)
    );

    if (__rBody.sharedPolicy === true) {
      __rLines.push('');
      __rLines.push(
        '⚠️ <b>POLICY COMPARTILHADA</b> — a retirada afeta <b>todos</b> os vínculos abaixo (' +
        __rTargets.length +
        '):'
      );

      for (const __rT of __rTargets) {
        __rLines.push(
          '• ' +
          __rEsc(__rT.customer ?? '-') +
          ' | ' +
          __rEsc(__rT.interfaceName ?? __rT.interface ?? '-') +
          ' | Peer: ' +
          __rEsc(__rT.peerAddress ?? __rT.peer ?? '-') +
          ' | ' +
          __rEsc(__rT.addressFamily ?? '-')
        );
      }
    }

    return {
      EVENTO: __rBody.event,
      PATCH: PATCH_VERSION,
      REENVIO: true,
      RESEND_VALIDO: true,
      REAL_ACTIVATED: true,
      SIMULACAO: false,
      VERIFICADO: true,
      EVENT_ID: __rBody.eventId ?? null,
      PROFILE_ID: __rProfileId,
      CLIENTE: __rBody.customer ?? null,
      EQUIPAMENTO: __rBody.device ?? null,
      INTERFACE: __rIf ?? null,
      FAMILIA: __rBody.addressFamily ?? null,
      PEER: __rBody.peer ?? null,
      PEERS_AFETADOS: __rPeers,
      BANDA_GBPS: __rBody.bandwidthGbps ?? null,
      TRAFEGO_GBPS: __rBody.trafficGbps ?? null,
      LIMITE_GBPS: __rBody.thresholdGbps ?? null,
      POLICY: __rBody.policy ?? null,
      BOGON_NODE: __rBogon,
      MITIGATION_NODE: __rMit,
      RT: __rBody.rt ?? null,
      POLICY_COMPARTILHADA: __rBody.sharedPolicy === true,
      OUTROS_TARGETS: __rTargets,
      OCORREU_EM: __rBody.occurredAt ?? null,
      READBACK_READ_AT: __rRb.readAt,
      telegramText: __rLines.join('\n'),
    };
  }

  // ==========================================================
  // CODIGO ORIGINAL - MITIGATION_VERIFIED
  // ==========================================================

  const b = $json.body ?? $json;
  const esc = (v) => v == null ? '' : String(v)
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/\r/g,'')
    .trim();

  const evento = b.event ?? null;
  const simulation = b.simulation === true;
  const verified = b.verified === true;
  const profileId = b.profileId ?? null;

  const bogonNode = b.bogonNode ?? null;
  const mitigationNode = b.mitigationNode ?? b.node ?? null;

  const realActivated =
    evento === 'MITIGATION_VERIFIED' &&
    simulation === false &&
    verified === true &&
    typeof profileId === 'string' &&
    profileId.length > 0;

  const lines = [
    '🛡️ <b>ALERTA NETVISION - MITIGAÇÃO DDoS</b>',
    ''
  ];

  if (b.customer)
    lines.push(`<b>Cliente:</b> ${esc(b.customer)}`);

  if (b.device)
    lines.push(`<b>Equipamento:</b> ${esc(b.device)}`);

  const interfaceName = b.interfaceName ?? b.interface;

  if (interfaceName)
    lines.push(`<b>Interface:</b> ${esc(interfaceName)}`);

  if (b.addressFamily)
    lines.push(`<b>Família:</b> ${esc(b.addressFamily)}`);

  lines.push('');

  if (b.trafficGbps != null)
    lines.push(`<b>Tráfego:</b> ${esc(b.trafficGbps)} Gbps`);

  if (b.bandwidthGbps != null)
    lines.push(`<b>Banda:</b> ${esc(b.bandwidthGbps)} Gbps`);

  if (b.thresholdGbps != null)
    lines.push(`<b>Limite:</b> ${esc(b.thresholdGbps)} Gbps`);

  lines.push('');

  if (b.policy)
    lines.push(`<b>Policy:</b> ${esc(b.policy)}`);

  if (bogonNode != null)
    lines.push(`<b>Node BOGONS:</b> ${esc(bogonNode)}`);

  if (mitigationNode != null)
    lines.push(`<b>Node mitigação:</b> ${esc(mitigationNode)}`);

  if (b.rt)
    lines.push(`<b>RT:</b> ${esc(b.rt)}`);

  if (b.peer)
    lines.push(`<b>Peer principal:</b> ${esc(b.peer)}`);

  lines.push('');
  lines.push(
    '✅ <b>MITIGAÇÃO ATIVADA E VERIFICADA NO EQUIPAMENTO</b>'
  );

  if (b.sharedPolicy) {
    lines.push('');
    lines.push('⚠️ <b>POLICY COMPARTILHADA</b>');

    for (const t of b.sharedPolicyTargets ?? []) {
      lines.push(
        `• ${esc(t.customer ?? '-')} | ${esc(t.interfaceName ?? '-')} | Peer: ${esc(t.peerAddress ?? '-')}`
      );
    }
  }

  // ==========================================================
  // S5 / REVIEW-07 - DETECCAO BLOQUEADA (nenhuma escrita)
  // Separado de `realActivated` por contrato: nunca e mitigacao aplicada.
  // ==========================================================
  const detectionBlocked =
    evento === 'MITIGATION_DETECTION_BLOCKED' &&
    simulation === true &&
    verified === false;

  const faltando = Array.isArray(b.fieldsUnavailable)
    ? b.fieldsUnavailable
    : [];

  const det = (v) =>
    v === null || v === undefined || v === ''
      ? '<i>indisponível</i>'
      : esc(v);

  const rateTxt = (gbps, mbps) => {
    if (gbps == null && mbps == null) return '<i>indisponível</i>';
    if (gbps != null && Number(gbps) >= 1) return esc(gbps) + ' Gbps';
    if (mbps != null) return esc(mbps) + ' Mbps';
    return esc(gbps) + ' Gbps';
  };

  const detLines = [];

  if (detectionBlocked) {
    detLines.push('🚨 <b>NETVISION - ATAQUE DETECTADO</b>', '');
    detLines.push('⚠️ <b>Mitigação automática NÃO aplicada</b> (execução desabilitada ou escrita não autorizada).');
    detLines.push('Nenhuma alteração foi feita no equipamento.', '');
    detLines.push(`<b>Cliente:</b> ${det(b.customer)}`);
    detLines.push(`<b>Equipamento:</b> ${det(b.device)}`);
    detLines.push(`<b>Interface:</b> ${det(interfaceName)}`);
    detLines.push(`<b>Família:</b> ${det(b.addressFamily)}`);
    detLines.push(`<b>Policy:</b> ${det(b.policy)}`);

    if (b.sharedPolicy === true) detLines.push('⚠️ <b>POLICY COMPARTILHADA</b>');

    detLines.push(`<b>Peer:</b> ${det(b.peer)}`, '');
    detLines.push(`<b>Tráfego medido:</b> ${rateTxt(b.trafficGbps, b.trafficMbps)}`);
    detLines.push(`<b>Limite:</b> ${rateTxt(b.thresholdGbps, b.thresholdMbps)}`);
    detLines.push(`<b>Direção:</b> ${det(b.direction)} (origem: ${det(b.directionSource)})`, '');
    detLines.push(`<b>Motivo do bloqueio:</b> ${det(b.blockedReason)}`);
    detLines.push(`<b>Episódio:</b> ${det(b.episodeId)}`);
    detLines.push(`<b>Detectado em:</b> ${det(b.occurredAt)}`);

    if (faltando.length) {
      detLines.push('', `⚠️ <b>Campos sem leitura:</b> ${esc(faltando.join(', '))}`);
    }

    detLines.push('', `Profile: <code>${det(profileId)}</code>`);
  }

  return {
    EVENTO: evento,
    SIMULACAO: simulation,
    VERIFICADO: b.verified ?? null,
    REAL_ACTIVATED: realActivated,
    EVENT_ID: b.eventId ?? null,
    PROFILE_ID: profileId,
    CLIENTE: b.customer ?? null,
    EQUIPAMENTO: b.device ?? null,
    INTERFACE: interfaceName ?? null,
    FAMILIA: b.addressFamily ?? null,
    PEER: b.peer ?? null,
    PEERS_AFETADOS: b.affectedPeers ?? [],
    BANDA_GBPS: b.bandwidthGbps ?? null,
    TRAFEGO_GBPS: b.trafficGbps ?? null,
    LIMITE_GBPS: b.thresholdGbps ?? null,
    POLICY: b.policy ?? null,
    BOGON_NODE: bogonNode,
    MITIGATION_NODE: mitigationNode,
    RT: b.rt ?? null,
    POLICY_COMPARTILHADA: b.sharedPolicy === true,
    OUTROS_TARGETS: b.sharedPolicyTargets ?? [],
    OCORREU_EM: b.occurredAt ?? null,
    telegramText: lines.join('\n'),
    DETECTION_BLOCKED: detectionBlocked,
    MOTIVO_BLOQUEIO: b.blockedReason ?? null,
    EPISODIO_ID: b.episodeId ?? null,
    DIRECAO: b.direction ?? null,
    ORIGEM_DIRECAO: b.directionSource ?? null,
    CAMPOS_INDISPONIVEIS: faltando,
    detectionText: detLines.join('\n')
  };
})()
}}

parameters.jsCode:
const input = $input.first().json;

const q =
  input.callback_query ||
  input.callbackQuery ||
  input.raw?.callback_query ||
  input.raw?.callbackQuery ||
  input;

const data = String(q.data ?? input.data ?? '');
const allowedChatId = '-5522540056';

const chatId = q.message?.chat?.id ?? null;
const userId = q.from?.id ?? null;
const username = q.from?.username ?? null;
const messageId = q.message?.message_id ?? null;
const callbackQueryId = q.id ?? null;

// Telefone: callback_data do Telegram tem limite de 64 BYTES.
let callbackBytes = 0;
for (const ch of data) {
  const cp = ch.codePointAt(0);
  callbackBytes += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
}

// RC4: rmc:<token> (cancelar) | rmx:<token> (confirmar)
const scopeMatch = /^(rmc|rmx):([A-Za-z0-9_-]{16,60})$/.exec(data);
const isScopeCallback = scopeMatch !== null && callbackBytes <= 64;
const isScopeConfirm = isScopeCallback && scopeMatch[1] === 'rmx';
const isScopeCancel = isScopeCallback && scopeMatch[1] === 'rmc';
const scopeToken = isScopeCallback ? scopeMatch[2] : '';

// Callbacks legados -> <comando>|<profileId>
const parts = data.split('|');
const legacyCmd = parts[0] ?? '';
const legacyProfileId = parts[1] ?? '';

const validCommands = new Set([
  'remove_confirm',
  'remove_execute',
  'remove_cancel',
]);

const legacyValid =
  parts.length === 2 &&
  validCommands.has(legacyCmd) &&
  legacyProfileId.length > 0 &&
  legacyProfileId.length <= 160 &&
  /^[a-zA-Z0-9_.:-]+$/.test(legacyProfileId);

const callbackValid = isScopeCallback ? true : legacyValid;

const cmd = isScopeCallback
  ? (isScopeConfirm ? 'scope_confirm' : 'scope_cancel')
  : legacyCmd;
const profileId = isScopeCallback ? '' : legacyProfileId;

const groupAuthorized = chatId !== null && String(chatId) === allowedChatId;
const userIdentified = userId !== null && callbackQueryId !== null;

// Politica de autorizacao IDENTICA ao workflow original: qualquer integrante
// do grupo autorizado pode solicitar, confirmar ou cancelar a retirada.
const authorized = callbackValid && groupAuthorized && userIdentified;

// REMOVE legado somente apos confirmar e autorizar
const action = authorized && cmd === 'remove_execute' ? 'REMOVE' : null;

// Auditoria: ID + username do operador.
const operatorRef = 'telegram:' + String(userId ?? 'desconhecido') + (username ? '(@' + username + ')' : '');

return [{
  json: {
    raw: input,
    callbackQueryId,
    chatId,
    userId,
    username,
    messageId,
    cmd,
    action,
    profileId,
    scopeToken,
    isScopeCallback,
    isScopeConfirm,
    isScopeCancel,
    callbackBytes,
    callbackValid,
    groupAuthorized,
    authorized,
    requestId: callbackQueryId ? ('telegram-' + callbackQueryId) : null,
    allowedChatId,
    canRemove: authorized && cmd === 'remove_execute',
    requestedBy: username ? ('@' + username) : String(userId ?? 'desconhecido'),
    operatorRef,
  },
}];

const input = $input.first().json;

// Compatível com respostas diretas ou encapsuladas em body.
let r = input.body ?? input;

if (typeof r === 'string') {
  try {
    r = JSON.parse(r);
  } catch {
    r = {
      ok: false,
      status: 'INVALID_RESPONSE',
      safeError: 'Resposta inválida recebida do NetVision'
    };
  }
}

const esc = (value) => {
  if (value === undefined || value === null) return '';

  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/\r/g, '')
    .trim();
};

// Recupera os dados originais do clique no Telegram.
let callback = {};

try {
  callback = $('Interpretar Callback').first().json;
} catch {
  callback = {};
}

const chatId = callback.chatId ?? null;
const requestedBy = callback.requestedBy ?? null;

const ok = r.ok === true;
const lines = [];

// Confirmação real: exige read-back verificado.
const removed =
  r.action === 'REMOVE' &&
  r.status === 'REMOVED_VERIFIED' &&
  r.verified === true &&
  ok;

const activated =
  r.action === 'ACTIVATE' &&
  r.status === 'ACTIVATED_VERIFIED' &&
  r.verified === true &&
  ok;

// Cabeçalho de acordo com o resultado.
if (removed) {
  lines.push('✅ <b>NETVISION - MITIGAÇÃO RETIRADA</b>');
  lines.push('✅ Remoção verificada no equipamento.');
} else if (activated) {
  lines.push('🛡️ <b>NETVISION - MITIGAÇÃO ATIVADA</b>');
  lines.push('✅ Ativação verificada no equipamento.');
} else if (r.action === 'STATUS' && ok) {
  lines.push('🔎 <b>NETVISION - CONSULTA DE STATUS</b>');
} else if (r.action === 'SIMULATE_REMOVE' && ok) {
  lines.push('🧪 <b>NETVISION - SIMULAÇÃO DE RETIRADA</b>');
  lines.push('Nenhuma remoção foi executada.');
} else if (r.action === 'SIMULATE_ACTIVATE' && ok) {
  lines.push('🧪 <b>NETVISION - SIMULAÇÃO DE ATIVAÇÃO</b>');
  lines.push('Nenhuma ativação foi executada.');
} else {
  lines.push('❌ <b>NETVISION - AÇÃO NÃO CONFIRMADA</b>');
}

lines.push('');

// Identificação da solicitação.
if (r.action) {
  lines.push(`<b>Ação:</b> ${esc(r.action)}`);
}

if (r.status) {
  lines.push(`<b>Status:</b> ${esc(r.status)}`);
}

if (r.profileId ?? callback.profileId) {
  lines.push(
    `<b>Perfil:</b> ${esc(r.profileId ?? callback.profileId)}`
  );
}

if (r.customer) {
  lines.push(`<b>Cliente:</b> ${esc(r.customer)}`);
}

if (r.device) {
  lines.push(`<b>Equipamento:</b> ${esc(r.device)}`);
}

if (r.interface) {
  lines.push(`<b>Interface:</b> ${esc(r.interface)}`);
}

if (r.addressFamily) {
  lines.push(`<b>Família:</b> ${esc(r.addressFamily)}`);
}

if (r.policy) {
  lines.push(`<b>Policy:</b> ${esc(r.policy)}`);
}

if (r.node !== undefined && r.node !== null) {
  lines.push(`<b>Node:</b> ${esc(r.node)}`);
}

if (r.bogonNode != null) {
  lines.push(`<b>Node BOGONS:</b> ${esc(r.bogonNode)}`);
}

if (r.mitigationNode != null) {
  lines.push(`<b>Node mitigação:</b> ${esc(r.mitigationNode)}`);
}

if (r.rt) {
  lines.push(`<b>RT:</b> ${esc(r.rt)}`);
}

// Peers afetados.
if (
  Array.isArray(r.affectedPeers) &&
  r.affectedPeers.length > 0
) {
  lines.push(
    `<b>Peers afetados:</b> ${r.affectedPeers.map(esc).join(', ')}`
  );
}

// Verificação física.
if (removed || activated) {
  lines.push('');
  lines.push('✅ <b>READ-BACK CONFIRMADO</b>');
} else if (
  r.verified === false &&
  ['ACTIVATE', 'REMOVE'].includes(r.action)
) {
  lines.push('');
  lines.push('⚠️ <b>Alteração não verificada no equipamento</b>');
}

// Policy compartilhada.
if (r.sharedPolicy) {
  lines.push('');
  lines.push('⚠️ <b>POLICY COMPARTILHADA</b>');

  if (Array.isArray(r.sharedPolicyTargets)) {
    for (const target of r.sharedPolicyTargets) {
      const parts = [];

      if (target.customer) {
        parts.push(esc(target.customer));
      }

      if (target.interfaceName) {
        parts.push(esc(target.interfaceName));
      }

      if (target.peerAddress) {
        parts.push(`Peer: ${esc(target.peerAddress)}`);
      }

      if (parts.length > 0) {
        lines.push(`• ${parts.join(' | ')}`);
      }
    }
  }
}

// Resultado do read-back Huawei.
if (r.verification?.summary) {
  lines.push('');
  lines.push(
    `<b>Read-back:</b> ${esc(r.verification.summary)}`
  );
}

// Erros e alertas operacionais.
if (r.safeError) {
  lines.push('');
  lines.push(`⚠️ <b>Aviso/Erro:</b> ${esc(r.safeError)}`);
}

// Código HTTP, quando disponível.
const httpStatus = input.statusCode ?? null;

if (typeof httpStatus === 'number' && httpStatus >= 400) {
  lines.push(`<b>HTTP:</b> ${httpStatus}`);
}

// Auditoria da solicitação.
lines.push('');

if (requestedBy) {
  lines.push(`<b>Solicitado por:</b> ${esc(requestedBy)}`);
}

if (r.requestId ?? callback.requestId) {
  lines.push(
    `<b>Requisição:</b> ${esc(r.requestId ?? callback.requestId)}`
  );
}

// Resposta pronta para Telegram.
return [{
  json: {
    ...r,
    chatId,
    requestedBy,
    removalVerified: removed,
    telegramText: lines.join('\n')
  }
}];

const p = $json.body ?? $json;

function esc(v) {
  if (v === null || v === undefined || v === '') return '';
  return String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function fmtDate(v) {
  if (!v) return '';
  try {
    return new Date(v).toLocaleString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      day: '2-digit',
