linhas.push('Nenhuma altera\u00E7\u00E3o foi feita no equipamento.');

return [{ json: {
  chatId: cb.chatId,
  messageId: cb.messageId,
  revoked: revogado,
  status: status,
  text: linhas.join('\n'),
} }];
